const inp = $input.first().json || {};
function handleFromIg(v){
  if(!v) return null;
  let s=String(v).trim();
  if(!s) return null;
  const m=s.match(/instagram\.com\/([^\/?#\s]+)/i);
  if(m){ s=m[1]; }
  else if(/^https?:\/\//i.test(s) || /^www\./i.test(s)){ return null; }
  s=s.replace(/^@/,'').replace(/[\/?#].*$/,'').trim().toLowerCase();
  if(!s || !/^[a-z0-9._]{1,30}$/.test(s)) return null;
  if(/^(p|reel|reels|explore|stories|tv|accounts|about)$/i.test(s)) return null;
  return s;
}
function normSite(v){
  if(!v) return null;
  let s=String(v).trim();
  if(!s) return null;
  if(!/^https?:\/\//i.test(s)) s='https://'+s;
  s=s.replace(/[#?].*$/,'').replace(/\/+$/,'');
  if(!/^https?:\/\/[^\/\s.]+\.[^\/\s]+/i.test(s)) return null;
  return s;
}
const igUsername=handleFromIg(inp.instagram);
const siteUrl=normSite(inp.website);
const hasIg=!!igUsername, hasSite=!!siteUrl;
return [{json:{
  name: inp.name || null,
  igUsername,
  igUrl: igUsername ? ('https://www.instagram.com/'+igUsername+'/') : null,
  siteUrl, hasIg, hasSite
}}];

const raws=$input.all().map(it=>it.json||{});
const looksProfile=(o)=>o&&(Array.isArray(o.latestPosts)||o.biography!==undefined||o.followersCount!==undefined);
const looksPost=(o)=>o&&(o.shortCode!==undefined||o.ownerUsername!==undefined||(o.url!==undefined&&o.likesCount!==undefined));
let p={}, posts=[];
if(raws.length && looksProfile(raws[0])){ p=raws[0]; posts=Array.isArray(p.latestPosts)?p.latestPosts:[]; }
else if(raws.some(looksPost)){ posts=raws.filter(looksPost); p={username:(posts[0]&&posts[0].ownerUsername)||null, fullName:(posts[0]&&posts[0].ownerFullName)||null, latestPosts:posts}; }
else if(raws.length){ p=raws[0]; posts=Array.isArray(p.latestPosts)?p.latestPosts:[]; }
const med=(arr)=>{const a=arr.filter(x=>typeof x==='number').sort((x,y)=>x-y);if(!a.length)return null;const m=Math.floor(a.length/2);return a.length%2?a[m]:Math.round((a[m-1]+a[m])/2);};
const medLikes=med(posts.map(x=>x.likesCount));
const medComments=med(posts.map(x=>x.commentsCount));
const followers=p.followersCount||null;
const eng=(followers&&medLikes!=null)?+(((medLikes+(medComments||0))/followers*100).toFixed(2)):null;
const mix={};
for(const x of posts){const t=x.type||'Unknown';mix[t]=(mix[t]||0)+1;}
const hc={};
for(const x of posts){for(const h of (x.hashtags||[])){hc[h]=(hc[h]||0)+1;}}
const topHashtags=Object.entries(hc).sort((a,b)=>b[1]-a[1]).slice(0,8).map(([tag,count])=>({tag,count}));
const lc={};
for(const x of posts){const l=x.locationName;if(l)lc[l]=(lc[l]||0)+1;}
const topLocations=Object.entries(lc).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([location,count])=>({location,count}));
let postsPerWeek=null;
const ts=posts.map(x=>x.timestamp?Date.parse(x.timestamp):null).filter(Boolean).sort((a,b)=>b-a);
if(ts.length>=2){const span=(ts[0]-ts[ts.length-1])/86400000;postsPerWeek=span>0?+((ts.length/span*7).toFixed(2)):null;}
const trimmed=posts.slice(0,24).map(x=>({url:x.url,type:x.type,caption:String(x.caption||'').slice(0,500),hashtags:x.hashtags||[],mentions:x.mentions||[],likesCount:x.likesCount,commentsCount:x.commentsCount,videoViewCount:x.videoViewCount,timestamp:x.timestamp,locationName:x.locationName||null}));
const raw={username:p.username,fullName:p.fullName,biography:p.biography,followersCount:p.followersCount,followsCount:p.followsCount,postsCount:p.postsCount,verified:p.verified,private:p.private,externalUrl:p.externalUrl,businessCategoryName:p.businessCategoryName,latestPosts:trimmed};
const metrics={followers,following:p.followsCount||null,posts:p.postsCount||null,medianLikes:medLikes,medianComments:medComments,engagementRatePct:eng,contentMix:mix,postsPerWeek,topHashtags,topLocations,analyzedPosts:posts.length};
const isEmpty=!p.username && posts.length===0;
return [{json:{ig:isEmpty?null:{raw,metrics}}}];

const norm=$('Normalize & validate').first().json;
let ig=null, site=null;
for(const it of $input.all()){const j=it.json||{}; if('ig' in j) ig=j.ig; if('site' in j) site=j.site;}
const sources_used=[], sources_missing=[];
if(norm.hasIg){ (ig&&ig.raw)?sources_used.push('instagram'):sources_missing.push('instagram'); }
if(norm.hasSite){ (site&&site.pages&&site.pages.length)?sources_used.push('website'):sources_missing.push('website'); }
const identifiers={ig_username:norm.igUsername,ig_url:norm.igUrl,website:norm.siteUrl,name:norm.name};
return [{json:{identifiers,evidence:{identifiers,ig,site},sources_used,sources_missing}}];

